import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {randomBytes,randomUUID} from 'node:crypto';
import {pathToFileURL} from 'node:url';
export async function verifyNativeRuntimeRoles({admin,merchants,pg,port,database,roleRoot}){
 for(const f of ['20261119160000_analytics_reader_pilot_read.sql','20261119170000_analytics_report_roles.sql','20261119180000_analytics_access_checker_roles.sql','20261120010000_runtime_principal_binding.sql'])await admin.query(await readFile(roleRoot+'/db/pending-migrations/'+f,'utf8'));
 const {createTenantPgClient}=await import(pathToFileURL(roleRoot+'/src/security/tenant-pg-client.js').href);
 const checks=[];const pools=[];const logins=[];
 async function principal(kind,m,i){const login='nordla_drill_'+i,password=randomBytes(32).toString('base64url');await admin.query('select nordla_runtime.provision($1,$2,$3)',[login,m,kind]);await admin.query('alter role '+login+' login password '+"'"+password+"'");const pool=new pg.Pool({host:'127.0.0.1',port,database,user:login,password,max:2});pools.push(pool);logins.push(login);return {login,pool,client:createTenantPgClient({pool,merchantId:m,profile:kind})};}
 try{
 const a=merchants[0],b=merchants[1];const readA=await principal('analytics_reader',a,0),readB=await principal('analytics_reader',b,1),financeA=await principal('finance_runtime',a,2),coreA=await principal('core_business_reader',a,3),reportA=await principal('analytics_report_reader',a,4),writerA=await principal('analytics_report_writer',a,5),accessA=await principal('analytics_access_checker',a,6);
 for(const x of [readA,readB,financeA,coreA,reportA,writerA,accessA])assert.equal(await x.client.verify(),true);
 await assert.rejects(createTenantPgClient({pool:readA.pool,merchantId:b,profile:'analytics_reader'}).verify());
 assert.deepEqual((await readA.client.select('merchants')).map(x=>x.id),[a]);assert.deepEqual((await readB.client.select('merchants')).map(x=>x.id),[b]);checks.push('real LOGIN principals: unfiltered merchant reads stay separate');
 const raw=await readA.pool.connect();try{await assert.rejects(raw.query('select id from merchants'));await raw.query("select set_config('app.merchant_id',$1,false)",[b]);await assert.rejects(raw.query('select id from merchants'),/RUNTIME_CONTEXT_FORBIDDEN/);await assert.rejects(raw.query('set role service_role'));await assert.rejects(raw.query('set role postgres'));await assert.rejects(raw.query('update nordla_runtime.principals set merchant_id=$1',[b]));}finally{raw.release();}checks.push('missing context, forged other-merchant context, privilege escalation and rebinding refused');
 assert.equal((await financeA.client.select('fin_documents')).length,1);assert.equal((await coreA.client.select('fin_documents')).length,1);assert.equal((await financeA.client.select('fin_documents',{merchant_id:'eq.'+b})).length,0);await assert.rejects(coreA.client.insert('fin_companies',[{merchant_id:a,name:'refused'}]));
 const company=(await financeA.client.insert('fin_companies',[{merchant_id:a,name:'Synthetic restricted writer'}]))[0];await financeA.client.upsert('fin_companies',[{id:company.id,merchant_id:a,name:'Synthetic upsert'}],{onConflict:'id'});assert.equal((await financeA.client.update('fin_companies',{merchant_id:'eq.'+a},{name:'Synthetic updated'}))[0].name,'Synthetic updated');await assert.rejects(financeA.client.update('fin_companies',{}, {name:'unfiltered refused'}));assert.equal((await financeA.client.update('fin_companies',{merchant_id:'eq.'+b},{name:'cross update refused'})).length,0);await assert.rejects(financeA.client.insert('fin_companies',[{merchant_id:b,name:'cross tenant refused'}]));checks.push('Finance reads/writes its merchant only; Core business role cannot write');
 const foreignDoc=(await admin.query('select id from fin_documents where merchant_id=$1 limit 1',[b])).rows[0].id;await assert.rejects(financeA.client.insert('fin_documents',[{merchant_id:a,doc_type:'credit_note',status:'DRAFT',related_document_id:foreignDoc,body:{}}]),e=>e.code==='FIN_REFERENCE_OUTSIDE_MERCHANT');checks.push('Finance foreign-key references cannot link a document to another merchant');
 const doc=(await financeA.client.insert('fin_documents',[{merchant_id:a,doc_type:'invoice',status:'DRAFT',currency:'EUR',issue_date:'2026-11-20',due_date:'2026-12-20',net_cents:100,vat_cents:21,gross_cents:121,revenue_basis:'standalone_b2b',body:{lines:[1]}}]))[0];
 const fn=(await admin.query("select pg_get_function_arguments(p.oid) args from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and proname='fin_issue_document' limit 1")).rows[0].args;
 const names=fn.split(',').map(s=>s.trim().split(' ')[0]);const vals=[a,doc.id,doc.version,'ISSUED','INV',4,'{prefix}-{year}-{seq}',2026,JSON.stringify({id:doc.id,number:'__NUMBER_PLACEHOLDER__',gross:121}),'__NUMBER_PLACEHOLDER__','2026-11-20T12:00:00Z',JSON.stringify({actor:{type:'merchant'},action:'ISSUED',detail:{n:'__NUMBER_PLACEHOLDER__'}})];
 const result=await financeA.client.rpc('fin_issue_document',Object.fromEntries(names.map((k,i)=>[k,vals[i]])));assert.ok(result);assert.equal((await financeA.client.select('fin_documents',{id:'eq.'+doc.id}))[0].status,'ISSUED');await assert.rejects(financeA.client.rpc('fin_issue_document',{p_merchant_id:b}));checks.push('actual SECURITY INVOKER invoice issuance succeeds without service_role');
 const flag={merchant_id:a,entity_type:'product',entity_id:randomUUID(),rule_code:'SYNTHETIC_DRILL',severity:'info'};await writerA.client.insert('data_quality_flags',[flag]);await assert.rejects(writerA.client.insert('data_quality_flags',[{...flag,merchant_id:b}]));await assert.rejects(writerA.client.delete('data_quality_flags',{merchant_id:'eq.'+a}));await assert.rejects(reportA.client.insert('products',[{merchant_id:a,title:'refused'}]));checks.push('report reader and flag writer remain separate; cross-merchant flags refused');
 const user=(await admin.query('select user_id from merchant_members where merchant_id=$1 limit 1',[a])).rows[0].user_id;assert.equal((await accessA.client.select('merchant_members',{select:'merchant_id,user_id,role,status,removed_at',merchant_id:'eq.'+a,user_id:'eq.'+user})).length,1);await assert.rejects(accessA.client.select('app_sessions',{select:'token_hash',user_id:'eq.'+user}));await assert.rejects(accessA.client.rpc('security_mfa_status',{p_merchant:b,p_user:user}));checks.push('identity checks expose no session secret and reject foreign MFA context');
 await admin.query('update nordla_runtime.principals set enabled=false where login_role=$1',[readA.login]);await assert.rejects(readA.client.select('merchants'));checks.push('disabling a principal closes existing pooled access on next request');
 return {principals:logins.length,checks};
 }finally{for(const p of pools)await p.end();}
}
